class Node {
  constructor(value, left = null, right = null) {
    this.value = value;
    this.left = left;
    this.right = right;
  }
}
const root = new Node(
  1,
  new Node(2, new Node(4), new Node(5)),
  new Node(3, null, new Node(6))
);

